setline("document.addEventListener('DOMContentLoaded'", r'''document.addEventListener('DOMContentLoaded',()=>{try{state.theme=localStorage.getItem(THEME_KEY)||'system'}catch(_){state.theme='system'}applyTheme(state.theme,false);bindStatic();restoreLocalSession();applyTheme(state.theme,false);renderAll();const result=selfTest();document.documentElement.dataset.runtimeReady='1';window.__RUNTIME_STATUS__=result});''')

helper_after_common = r'''
function activeCompIndices(node){const all=nodeCompetencies(node);return state.selectedComps.size?all.filter(i=>state.selectedComps.has(i)):all}
function activeCommonCompetencies(a,b){const all=commonCompetencies(a,b);return state.selectedComps.size?all.filter(i=>state.selectedComps.has(i)):all}
'''.strip('\n')

session_helpers = r'''
function setErrorStatus(id,status){const e=errorById(id);if(!e)return;const previous=errorStatusMeta(id);let comment='';let method='manual';if(status==='fixed'){comment=prompt('Кратко укажите, где или как исправлена ошибка:','')??'';method='external';if(!comment.trim()){toast('Для статуса «Исправлена» нужен комментарий');return}}else if(status==='not_relevant'){comment=prompt('Укажите, почему ошибка не актуальна:','')??'';method='not_relevant';if(!comment.trim()){toast('Для статуса «Не актуальна» нужен комментарий');return}}const at=new Date().toISOString();if(status==='open'){delete state.errorStates[id];if(!baseErrors().some(x=>x.id===id))delete state.errorArchive[id]}else{const snapshot=deep(e);for(const key of ['status','status_comment','status_at','status_method'])delete snapshot[key];state.errorArchive[id]=snapshot;state.errorStates[id]={status,comment:comment.trim(),at,method}}state.changeLog.push({at,type:'error_status',error_id:id,previous_status:previous.status||'open',new_status:status,comment:comment.trim(),method,role:state.role,semester:e.semester,node_ids:deep((e.node_ids||{})[state.role]||[])});toast(status==='open'?'Ошибка возвращена в работу':`Статус: ${statusLabel(status)}`);renderAll()}
function applyTheme(theme,save=true){if(!['system','light','dark'].includes(theme))theme='system';state.theme=theme;const dark=theme==='dark'||(theme==='system'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('theme-dark',!!dark);document.documentElement.dataset.theme=theme;if(byId('themeSelect'))byId('themeSelect').value=theme;if(save)try{localStorage.setItem(THEME_KEY,theme)}catch(_){ }schedulePersist()}
function sessionPayload(){return{schema:SESSION_SCHEMA,version:'v0.4',saved_at:new Date().toISOString(),program:{specialty_code:state.data.meta.specialty_code,year:state.data.meta.year},state:{data:deep(state.data),role:state.role,selectedComps:[...state.selectedComps],showZero:state.showZero,showContinuations:state.showContinuations,onlyViolations:state.onlyViolations,query:state.query,selectedNode:state.selectedNode,selectedError:state.selectedError,activeTab:state.activeTab,editMode:state.editMode,changeLog:deep(state.changeLog),semesterFocus:state.semesterFocus,errorStates:deep(state.errorStates),errorArchive:deep(state.errorArchive),theme:state.theme}}}
function applySessionPayload(payload){if(!payload||payload.schema!==SESSION_SCHEMA||payload.program?.specialty_code!==state.data.meta.specialty_code||!payload.state?.data?.roles?.kiber||!payload.state?.data?.roles?.devops||payload.state.data.catalog?.length!==43)throw new Error('Файл сессии не соответствует этой визуализации');const x=payload.state;state.data=deep(x.data);state.role=state.data.roles[x.role]?x.role:'kiber';state.selectedComps=new Set((x.selectedComps||[]).map(Number).filter(i=>Number.isInteger(i)&&i>=0&&i<43));state.showZero=x.showZero!==false;state.showContinuations=x.showContinuations!==false;state.onlyViolations=!!x.onlyViolations;state.query=String(x.query||'');state.selectedNode=x.selectedNode&&nodeById(x.selectedNode)?x.selectedNode:null;state.selectedError=x.selectedError||null;state.activeTab=x.activeTab==='errors'?'errors':'details';state.editMode=!!x.editMode;state.changeLog=Array.isArray(x.changeLog)?deep(x.changeLog):[];state.semesterFocus=x.semesterFocus||null;state.errorStates=x.errorStates&&typeof x.errorStates==='object'?deep(x.errorStates):{};state.errorArchive=x.errorArchive&&typeof x.errorArchive==='object'?deep(x.errorArchive):{};state.theme=['system','light','dark'].includes(x.theme)?x.theme:state.theme}
function saveWorkingSession(){downloadJSON('рабочая_сессия_траектории_ИБ_v0.4.json',sessionPayload());toast('Рабочая сессия сохранена')}
function loadWorkingSession(file){const reader=new FileReader();reader.onload=()=>{try{const payload=JSON.parse(String(reader.result));applySessionPayload(payload);applyTheme(state.theme);renderAll();toast('Рабочая сессия загружена')}catch(err){alert(`Не удалось загрузить сессию: ${err.message}`)}};reader.onerror=()=>alert('Не удалось прочитать файл сессии');reader.readAsText(file,'utf-8')}
function persistLocal(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(sessionPayload()))}catch(_){ }}
function schedulePersist(){clearTimeout(state.persistTimer);state.persistTimer=setTimeout(persistLocal,250)}
function restoreLocalSession(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)applySessionPayload(JSON.parse(raw))}catch(_){try{localStorage.removeItem(STORAGE_KEY)}catch(__){ }}}
function syncStaticControls(){if(byId('searchInput'))byId('searchInput').value=state.query;if(byId('showZero'))byId('showZero').checked=state.showZero;if(byId('showContinuations'))byId('showContinuations').checked=state.showContinuations;if(byId('onlyViolations'))byId('onlyViolations').checked=state.onlyViolations;if(byId('themeSelect'))byId('themeSelect').value=state.theme}
'''.strip('\n')

new_lines = []
skip_next_panel_listener = False
for idx, line in enumerate(lines):
    if skip_next_panel_listener:
        skip_next_panel_listener = False
        if line.startswith("  panel.querySelectorAll"):
            continue
    matched = False
    for prefix, replacement in replacements.items():
        if line.startswith(prefix):
            new_lines.extend(replacement.splitlines())
            matched = True
            if prefix == "function renderPanel":
                skip_next_panel_listener = True
            break
    if matched:
        continue
    new_lines.append(line)
    if line.startswith("function commonCompetencies"):
        new_lines.extend(helper_after_common.splitlines())
    if line.startswith("function downloadJSON"):
        new_lines.extend(session_helpers.splitlines())

s = "\n".join(new_lines) + "\n"

# Replace the two-line renderPanel block after line-oriented patching.
start = s.find("function renderPanel(){")
if start < 0:
    raise SystemExit('renderPanel start not found')
end = s.find("function renderErrorCount", start)
if end < 0:
    raise SystemExit('renderPanel end not found')
render_panel = r'''function renderPanel(){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===state.activeTab));const panel=byId('panel');if(state.activeTab==='errors'){panel.innerHTML=errorsPanel()}else if(state.selectedError&&errorById(state.selectedError)){panel.innerHTML=errorPanel(errorById(state.selectedError))}else if(state.selectedNode&&nodeById(state.selectedNode)){panel.innerHTML=nodePanel(nodeById(state.selectedNode))}else{panel.innerHTML=overviewPanel()}panel.querySelectorAll('[data-error-id]').forEach(b=>b.onclick=()=>selectError(b.dataset.errorId));panel.querySelectorAll('[data-focus-node]').forEach(b=>b.onclick=()=>focusNode(b.dataset.focusNode));panel.querySelectorAll('[data-error-status]').forEach(b=>b.onclick=()=>setErrorStatus(state.selectedError,b.dataset.errorStatus));byId('applyEdit')?.addEventListener('click',applyEdits);byId('showErrorOnMap')?.addEventListener('click',()=>selectError(state.selectedError));byId('editErrorNode')?.addEventListener('click',()=>{const e=errorById(state.selectedError);const id=((e.node_ids||{})[state.role]||[])[0];if(id){state.editMode=true;state.selectedNode=id;state.selectedError=null;renderAll()}});byId('exportError')?.addEventListener('click',()=>downloadJSON(`ошибка_${state.selectedError}.json`,errorById(state.selectedError)))}
'''
s = s[:start] + render_panel + s[end:]

template_path.write_text(s, encoding="utf-8")

b = build_path.read_text(encoding="utf-8")
b = b.replace('VERSION = "v0.3"', 'VERSION = "v0.4"')
b = b.replace('Все назначенные компетенции постоянно видны на карточках; линии включаются группами или по отдельности', 'Без активного фильтра карточки показывают все назначенные компетенции; при выборе группы или отдельных компетенций карточки и фокус показывают только активный набор')
b = b.replace('- постоянные метки всех компетенций;', '- полный набор компетенций без фильтра и только выбранные метки при активном фильтре;')
b = b.replace('- развернутая диагностика, локальное редактирование и экспорт изменений.', '- развернутая диагностика, статусы ошибок, светлая/тёмная тема, локальное редактирование, сохранение/загрузка сессии и раздельный экспорт снимка и журнала.')
b = b.replace('Изменения сохраняются только в открытой странице. Для передачи результата используйте кнопку «Экспорт изменений».', 'Изменения и статусы ошибок автосохраняются в локальном хранилище текущего браузера. Для переноса между компьютерами используйте «Сохранить сессию» и «Загрузить сессию». Прямая запись в Excel не выполняется.')
b = b.replace('required_markers = ["window.__TRAJECTORY_DATA__", "data-runtime-ready", "SOFT_DEFICIT", "show-group", "error-card"]', 'required_markers = ["window.__TRAJECTORY_DATA__", "data-runtime-ready", "data-v04-self-test", "SOFT_DEFICIT", "show-group", "error-card", "themeSelect", "saveSessionBtn", "errorStates"]')
build_path.write_text(b, encoding="utf-8")

